        { filename: 'sample_02.jpg', url: 'https://picsum.photos/id/11/800/600', thumbnail_url: 'https://picsum.photos/id/11/200/200' },
        { filename: 'sample_03.jpg', url: 'https://picsum.photos/id/12/800/600', thumbnail_url: 'https://picsum.photos/id/12/200/200' },
      ]
    });
  }),

  // Start Analysis
  http.post('*/api/analysis/run', async () => {
    return HttpResponse.json({
      success: true,
      percentage: 98.5,
      matched_pixels: 1200000,
      total_pixels: 1218274,
      processed_image_url: '/output/Benagol/sample_result.png',
      debug_images: [
        {title: 'Color Mask', url: '/output/Benagol/mask.png'},
        {title: 'Contours', url: '/output/Benagol/contours.png'}
      ]
    });
  }),

  // Get Logs
  http.get('*/api/logs', () => {
    return HttpResponse.json([
      { timestamp: new Date().toISOString(), level: 'info', module: 'core', message: 'Pipeline initialized.' },
      { timestamp: new Date().toISOString(), level: 'info', module: 'cc', message: 'Detecting color checker...' },
    ]);
  }),
];

