                      <div>
                        <label className="text-[10px] text-neutral-500 uppercase font-bold mb-1 block">Min Area</label>
                        <input
                          type="number"
                          step="0.0001"
                          value={options.aggMinArea}
                          onChange={(e) => setOptions({ ...options, aggMinArea: parseFloat(e.target.value) })}
