import createPlotlyComponent from 'react-plotly.js/factory';
import { Loader2, AlertCircle } from 'lucide-react';

const Plot = createPlotlyComponent(Plotly);

interface HSVPoint {
  hsv: number[];
  rgb: number[];
  isInside: boolean;
}

interface HSVDistributionPlotProps {
  data: any;
  isLoading: boolean;
  error: any;
}

export const HSVDistributionPlot: React.FC<HSVDistributionPlotProps> = ({ data, isLoading, error }) => {
  if (isLoading) {
    return (
      <div className="bg-neutral-900 border border-neutral-800 rounded-2xl p-12 flex flex-col items-center justify-center gap-4">
        <Loader2 className="w-8 h-8 animate-spin text-green-600" />
        <p className="text-sm text-neutral-500 font-medium">Calculating HSV Distribution...</p>
      </div>
    );
  }

  if (error || !data) {
    return (
      <div className="bg-neutral-900 border border-neutral-800 rounded-2xl p-12 flex flex-col items-center justify-center gap-4 text-red-500">
        <AlertCircle className="w-8 h-8" />
        <p className="text-sm font-medium">Failed to load HSV data. Ensure calibration images are assigned.</p>
      </div>
    );
  }

  const { lower_hsv, upper_hsv, dataset_debug_info } = data;

  const allPoints: HSVPoint[] = [];
  dataset_debug_info.forEach((item: any) => {
    item.hsv_colors.forEach((hsv: number[], idx: number) => {
      // Python BGR -> RGB for display
      const bgr = item.bgr_colors[idx];
      const rgb = [bgr[2], bgr[1], bgr[0]];

      const isInside = hsv.every((v, i) => v >= lower_hsv[i] && v <= upper_hsv[i]);

      allPoints.push({ hsv, rgb, isInside });
    });
  });

  const insidePoints = allPoints.filter(p => p.isInside);
  const outsidePoints = allPoints.filter(p => !p.isInside);

  const traceInside = {
    x: insidePoints.map(p => p.hsv[0]),
    y: insidePoints.map(p => p.hsv[1]),
    z: insidePoints.map(p => p.hsv[2]),
    mode: 'markers',
    type: 'scatter3d',
    name: 'Inside Range',
    marker: {
      size: 4,
      color: insidePoints.map(p => `rgb(${p.rgb[0]},${p.rgb[1]},${p.rgb[2]})`),
      opacity: 0.8
    }
  };

  const traceOutside = {
    x: outsidePoints.map(p => p.hsv[0]),
    y: outsidePoints.map(p => p.hsv[1]),
    z: outsidePoints.map(p => p.hsv[2]),
    mode: 'markers',
    type: 'scatter3d',
    name: 'Outliers',
    marker: {
      size: 6,
      symbol: 'x',
      color: outsidePoints.map(p => `rgb(${p.rgb[0]},${p.rgb[1]},${p.rgb[2]})`),
      line: {
        color: 'red',
        width: 1
      },
      opacity: 1
    }
  };

  // Draw the range box
  const boxCorners = [];
  const [hmin, smin, vmin] = lower_hsv;
  const [hmax, smax, vmax] = upper_hsv;

  // Box lines logic
  const boxTraces = [];
  const x = [hmin, hmax];
  const y = [smin, smax];
  const z = [vmin, vmax];

  // Helper to add a line between two points
  const addLine = (p1: number[], p2: number[]) => {
    boxTraces.push({
      type: 'scatter3d',
      mode: 'lines',
      x: [p1[0], p2[0]],
      y: [p1[1], p2[1]],
      z: [p1[2], p2[2]],
      line: { color: 'red', width: 2 },
      showlegend: false,
      hoverinfo: 'none'
    });
  };

  // 12 edges of the cube
  for (let i = 0; i < 2; i++) {
    for (let j = 0; j < 2; j++) {
      addLine([x[i], y[j], z[0]], [x[i], y[j], z[1]]);
      addLine([x[i], y[0], z[j]], [x[i], y[1], z[j]]);
      addLine([x[0], y[i], z[j]], [x[1], y[i], z[j]]);
    }
  }

  return (
    <div className="bg-neutral-900 border border-neutral-800 rounded-2xl overflow-hidden p-4">
      <div className="flex items-center justify-between mb-4 px-2">
        <div>
          <h3 className="text-lg font-bold text-white">HSV Range Preview</h3>
          <p className="text-[10px] text-neutral-500 uppercase tracking-widest font-bold">Dynamic 3D Distribution</p>
        </div>
        <div className="flex gap-4 text-[10px] font-bold">
          <div className="flex items-center gap-1.5">
            <div className="w-2 h-2 rounded-full bg-green-500"></div>
            <span className="text-neutral-400">TARGET RANGE</span>
          </div>
          <div className="flex items-center gap-1.5">
            <div className="w-2 h-2 rounded-full bg-red-500"></div>
            <span className="text-neutral-400">OUTLIERS (X)</span>
          </div>
        </div>
      </div>

      <div className="w-full h-[500px]">
        <Plot
          data={[traceInside, traceOutside, ...boxTraces]}
          layout={{
            autosize: true,
            paper_bgcolor: 'rgba(0,0,0,0)',
            plot_bgcolor: 'rgba(0,0,0,0)',
            margin: { l: 0, r: 0, b: 0, t: 0 },
            scene: {
              xaxis: { title: 'Hue', range: [0, 180], color: '#737373', gridcolor: '#262626' },
              yaxis: { title: 'Saturation', range: [0, 255], color: '#737373', gridcolor: '#262626' },
              zaxis: { title: 'Value', range: [0, 255], color: '#737373', gridcolor: '#262626' },
